import { existsSync, readFileSync } from 'node:fs';
import { createDemuxer, type Packet } from '../src/core/demux';
import { opusPacketDuration } from '../src/core/demux/webm';
import { assert, test } from './harness';

// Fixtures generated by tests/make-fixtures.sh (ffmpeg) into /tmp/mr
const FIX = '/tmp/mr';

function feed(file: string, mime: string, splitter: (len: number) => number[]): Packet[] {
  const data = new Uint8Array(readFileSync(`${FIX}/${file}`));
  const d = createDemuxer(mime)!;
  const out: Packet[] = [];
  let p = 0;
  for (const n of splitter(data.length)) {
    out.push(...d.push(data.slice(p, p + n), 0));
    p += n;
  }
  if (p < data.length) out.push(...d.push(data.slice(p), 0));
  return out;
}

const whole = (len: number) => [len];
const random = (len: number) => {
  const parts: number[] = [];
  let left = len;
  let seed = 12345;
  while (left > 0) {
    seed = (seed * 1103515245 + 12345) & 0x7fffffff;
    const n = Math.min(left, 1 + (seed % 7000));
    parts.push(n);
    left -= n;
  }
  return parts;
};
const tiny = (len: number) => Array.from({ length: Math.ceil(len / 13) }, () => 13);

function check(pk: Packet[], count: number, bytes: number, lastTs: number, codec: string) {
  assert(pk.length === count, `packet count ${pk.length} != ${count}`);
  const total = pk.reduce((a, p) => a + p.data.length, 0);
  assert(total === bytes, `bytes ${total} != ${bytes}`);
  assert(Math.abs(pk[pk.length - 1].ts - lastTs) < 0.03, `last ts ${pk[pk.length - 1].ts} vs ${lastTs}`);
  assert(pk[0].config.codec === codec, `codec ${pk[0].config.codec}`);
  for (let i = 1; i < pk.length; i++) assert(pk[i].ts > pk[i - 1].ts, 'monotonic ts');
}

const have = existsSync(`${FIX}/a.webm`);

test('WebM (known-size clusters) demux, any chunking', () => {
  if (!have) return console.log('    (skipped: no fixtures)');
  for (const s of [whole, random, tiny]) check(feed('a.webm', 'audio/webm; codecs="opus"', s), 601, 204438, 12.0, 'opus');
  const pk = feed('a.webm', 'audio/webm', whole);
  assert(pk[0].config.description && pk[0].config.description.length >= 19, 'OpusHead present');
  assert(Math.abs(pk[5].dur - 0.02) < 1e-9, 'opus 20ms frames');
});

test('WebM (unknown-size live clusters) demux', () => {
  if (!have) return;
  for (const s of [whole, random, tiny]) check(feed('live.webm', 'audio/webm', s), 601, 204438, 12.0, 'opus');
});

test('fMP4 AAC demux, any chunking', () => {
  if (!have) return;
  for (const s of [whole, random, tiny]) {
    const pk = feed('a.mp4', 'audio/mp4; codecs="mp4a.40.2"', s);
    check(pk, 518, 192511, 12.0, 'mp4a.40.2');
    assert(pk[0].config.sampleRate === 44100 && pk[0].config.channels === 2, 'aac config');
  }
});

test('Opus TOC duration', () => {
  assert(opusPacketDuration(new Uint8Array([0xfc])) === 0.02, 'CELT FB 20ms'); // config 31, code 0
  assert(opusPacketDuration(new Uint8Array([0xfd])) === 0.04, 'two frames');
  assert(opusPacketDuration(new Uint8Array([0x18])) === 0.06, 'SILK 60ms');
});

// YouTube (SABR) appends clusters in ~16 KB pieces and, on seek / quality switch, abandons a
// partially appended cluster and continues with a fresh cluster (sometimes after a new init).
function clusterStarts(b: Uint8Array): number[] {
  const out: number[] = [];
  for (let i = 0; i + 4 <= b.length; i++) if (b[i] === 0x1f && b[i + 1] === 0x43 && b[i + 2] === 0xb6 && b[i + 3] === 0x75) out.push(i);
  return out;
}

test('WebM: recovers after an abandoned partial cluster (SABR-style)', () => {
  if (!have) return;
  const data = new Uint8Array(readFileSync(`${FIX}/a.webm`));
  const cs = clusterStarts(data);
  assert(cs.length >= 4, `clusters ${cs.length}`);
  const init = data.subarray(0, cs[0]);
  const d = createDemuxer('audio/webm')!;
  const out: Packet[] = [];
  out.push(...d.push(init.slice(), 0));
  // cluster 0 fully, in 16 KB pieces
  for (let p = cs[0]; p < cs[1]; p += 16384) out.push(...d.push(data.slice(p, Math.min(p + 16384, cs[1])), 0));
  // cluster 1: only the first 5000 bytes, then abandoned
  out.push(...d.push(data.slice(cs[1], cs[1] + 5000), 0));
  // jump: cluster 3 complete (no init), then a re-sent init + cluster 4 piecewise
  out.push(...d.push(data.slice(cs[3], cs[4]), 0));
  out.push(...d.push(init.slice(), 0));
  const end4 = cs[5] ?? data.length;
  for (let p = cs[4]; p < end4; p += 16384) out.push(...d.push(data.slice(p, Math.min(p + 16384, end4)), 0));
  const ref = feed('a.webm', 'audio/webm', whole);
  // reference packets of a cluster = demux(init + that cluster) alone
  const clusterPk = (k: number) => {
    const dd = createDemuxer('audio/webm')!;
    dd.push(init.slice(), 0);
    return dd.push(data.slice(cs[k], cs[k + 1] ?? data.length), 0);
  };
  const want = [...feed('a.webm', 'audio/webm', whole).filter((p) => p.ts < clusterPk(1)[0].ts - 1e-6), ...clusterPk(3), ...clusterPk(4)];
  const firstOf1 = clusterPk(1)[0].ts;
  const got = out.filter((p) => p.ts < firstOf1 - 1e-6 || p.ts >= clusterPk(3)[0].ts - 1e-6);
  assert(got.length >= want.length, `packets ${got.length} vs expected ≥ ${want.length}`);
  for (const w of want) {
    const g = out.find((x) => Math.abs(x.ts - w.ts) < 1e-6);
    assert(g && g.data.length === w.data.length, `packet @${w.ts.toFixed(3)} present`);
  }
  void ref;
});
